"""Datasets of (ψ_t, V) -> ψ_{t+Δt} pairs generated by the exact solver.

Models see a real tensor with 3 channels per grid point: Re ψ, Im ψ and V / V_SCALE.
"""
from dataclasses import dataclass

import torch

from lab.physics.schrodinger import Grid, potentials_sharp, potentials_smooth, random_states, trajectory

V_SCALE = 5.0  # keeps the potential channel at O(1) like the wavefunction channels


@dataclass
class WaveData:
    traj: torch.Tensor  # (n_traj, steps+1, n) complex64
    V: torch.Tensor     # (n_traj, n) float32

    def pairs(self) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        """Flatten all consecutive steps into (psi_in, V, psi_out) pairs."""
        n_traj, t, n = self.traj.shape
        psi_in = self.traj[:, :-1].reshape(-1, n)
        psi_out = self.traj[:, 1:].reshape(-1, n)
        V = self.V.unsqueeze(1).expand(n_traj, t - 1, n).reshape(-1, n)
        return psi_in, V, psi_out


def make_data(n_traj: int, family: str, grid: Grid, dt: float, steps: int,
              substeps: int, seed: int) -> WaveData:
    gen = torch.Generator().manual_seed(seed)
    potentials = {"smooth": potentials_smooth, "sharp": potentials_sharp}[family]
    V = potentials(n_traj, grid, gen)
    psi0 = random_states(n_traj, grid, gen)
    traj = trajectory(psi0, V, grid, dt, steps, substeps)
    return WaveData(traj.to(torch.complex64), V.to(torch.float32))


def to_channels(psi: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
    """(batch, n) complex + (batch, n) real -> (batch, 3, n) real."""
    return torch.stack([psi.real, psi.imag, V / V_SCALE], dim=1)
